  for (const h of HOUSES) {
    const towardLobby = h.a === 1 ? "east" : "west";
    const intoFlat = h.a === 1 ? "west" : "east";
    const door = (x, y, z, facing) => {
      g.set(x, y, z, ...B.door("dark_oak", facing, "lower"));
      g.set(x, y + 1, z, ...B.door("dark_oak", facing, "upper"));
