    door(h.lw, 2, 22, towardLobby);
    door(h.lw, 9, 20, intoFlat);
    door(h.lw, 14, 11, intoFlat);
    door(h.door, 2, 24, "south");
    g.set(h.door, 4, 24, "bricks");
